{
  "findings": [
    {
      "ref": "[D173]",
      "area": "contact",
      "claim": "A parent reports that Roblox allows voice chat in some games and that this can let children talk to strangers.",
      "stance": "risk",
      "quote": "Roblox has social features like text chat and voice chat in some games. While these features encourage social interaction, they also open the door to kids talking to people they don't know and possibly cyberbullying."
    },
    {
      "ref": "[D173]",
      "area": "money",
      "claim": "A parent reports that Roblox encourages spending on Robux through limited-time events and social pressure.",
      "stance": "risk",
      "quote": "Roblox encourages spending on its virtual currency, \"Robux,\" through limited-time events, exclusive items, and social pressure. Many platforms like this use \"freemium\" features, where spending money enhances the experience, so it's important to set boundaries early on."
    },
    {
      "ref": "[D173]",
      "area": "data",
      "claim": "A parent reports that Roblox collects user data and shares it with third parties for advertising, and that this data can be deleted.",
      "stance": "neutral",
      "quote": "Roblox collects user data and uses it for advertising and service improvement; users can request deletion of their data through account settings."
    },
    {
      "ref": "[D173]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox's age filters are not strict and that under‑13 users can still access games rated for older ages.",
      "stance": "risk",
      "quote": "Roblox doesn't have strict age restrictions, so kids under 13 can play alongside teens and adults. With so many players and an endless number of games, not all games are suitable for young children, and some inappropriate content can get through the age filters."
    },
    {
      "ref": "[D173]",
      "area": "content",
      "claim": "A parent reports seeing games with adult themes, sexual content, and bullying in Roblox.",
      "stance": "risk",
      "quote": "Because Roblox is user-generated, kids may still run into inappropriate content despite the platform's safety filters. This includes \"condo games\" (which usually feature adult themes and sexual content), violent games, gambling-style play, and even games that may have bullying or hate speech."
    },
    {
      "ref": "[D173]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced safety concerns and regulatory scrutiny over its handling of under‑13 users.",
      "stance": "risk",
      "quote": "Following safety concerns, Roblox is rolling out new protections for under‑13 users in November and December 2024. These updates include mandatory age ratings for games, limits on social spaces, and restrictions on unmoderated content. Since these changes are new and won't be fully enforced until 2025, we're not sure what their impact will be."
    }
  ]
}
